window.RI2_UNITS = {"12":{"unit":12,"code":"RI2-U12","title":"GOING TO EXTREMES","startNumber":271,"endNumber":287,"entries":[{"number":271,"term":"go to (any) extremes to do st","sourceTerm":"go to (any) extremes to do st","spoken":"go to (any) extremes to do something","ipa":"go /ɡoʊ/ · extremes /ɛˈkstriːmz/","type":"phrase / pattern","meaning":"làm mọi cách để làm gì…","definition":"To take unusually severe, difficult, or risky action in order to achieve something.","note":"go to extremes to V; thường hàm ý hành động vượt xa mức bình thường và có thể thiếu hợp lí.","example":"Some explorers go to extremes to reach places that few people have visited."},{"number":272,"term":"cliff","sourceTerm":"cliff (n)","spoken":"cliff","ipa":"cliff /klɪf/","type":"noun","meaning":"vách đá, vách núi","definition":"A high, steep face of rock, especially beside the sea or a valley.","note":"","example":"Strong winds forced the climbers to remain several metres from the edge of the cliff."},{"number":273,"term":"such + noun ~ so + adjective/adverb","sourceTerm":"such + noun ~ so + adjective/adverb","spoken":"such + noun , so + adjective or adverb","ipa":"such /sʌtʃ/ · so /soʊ/","type":"phrase / pattern","meaning":"như vậy, đến mức như vậy (đứng trước danh từ) ~ quá, đến mức như vậy (đứng trước tính từ hoặc trạng từ)","definition":"Such comes before a noun phrase, while so comes before an adjective or adverb to express a high degree.","note":"such + (a/an) + tính từ + danh từ; trong cách dùng này such quy chiếu loại/tính chất đã nêu, khác so + tính từ/trạng từ.","example":"The conditions were so severe that the team stopped; such conditions made a safe climb impossible."},{"number":274,"term":"thrill · thrilling · thrilled · thriller","sourceTerm":"thrill · thrilling · thrilled · thriller","spoken":"thrill , thrilling , thrilled , thriller","ipa":"thrill /θrɪl/ · thrilling /ˈθrɪlɪŋ/ · thrilled /θrɪld/ · thriller /ˈθrɪlɚ/","type":"noun · noun · adjective","meaning":"cảm giác hồi hộp, phấn khích · gây hồi hộp, phấn khích · cảm thấy phấn khích · truyện hoặc phim giật gân","definition":"A thrill is a sudden feeling of excitement; thrilling causes excitement, thrilled describes the person feeling it, and a thriller is an exciting story.","note":"thrilling tả sự vật gây cảm giác; thrilled tả người cảm thấy phấn khích. thriller là thể loại truyện/phim, không phải người phấn khích.","example":"The thrilling descent gave the climber a powerful thrill, although her family was less thrilled."},{"number":275,"term":"parachute","sourceTerm":"parachute (n)","spoken":"parachute","ipa":"parachute /ˈpɛrəˌʃuːt/","type":"noun","meaning":"dù (nhảy dù)","definition":"A large fabric device that slows a person's or object's fall through the air.","note":"","example":"The athlete opened her parachute soon after jumping from the aircraft."},{"number":276,"term":"steer","sourceTerm":"steer (v)","spoken":"steer","ipa":"steer /stɪr/","type":"verb","meaning":"điều hướng","definition":"To control the direction in which a vehicle, boat, or moving object travels.","note":"steer a car/boat; steer toward/away from. steer còn dùng bóng: steer a discussion in a new direction.","example":"By pulling the control lines, the pilot steered the parachute toward the landing area."},{"number":277,"term":"aisle","sourceTerm":"aisle (n)","spoken":"aisle","ipa":"aisle /aɪl/","type":"noun","meaning":"lối đi giữa các hàng ghế/kệ","definition":"A passage between rows of seats, shelves, or other fixed objects.","note":"aisle /aɪl/ có chữ s không phát âm; aisle seat: ghế cạnh lối đi.","example":"For safety, passengers must keep the aircraft aisle clear before take-off."},{"number":278,"term":"emerge · emergence # emergency","sourceTerm":"emerge · emergence # emergency","spoken":"emerge , emergence , emergency","ipa":"emerge /ɪˈmɝːdʒ/ · emergence /ɪˈmɝːdʒəns/ · emergency /ɪˈmɝːdʒənsi/","type":"verb · noun · noun","meaning":"nổi lên, xuất hiện · sự xuất hiện · tình trạng khẩn cấp","definition":"To appear or come out; emergence is the process of appearing, while an emergency is a dangerous situation requiring immediate action.","note":"emerge và emergence là các từ cùng gốc. emergency chỉ tình trạng khẩn cấp và không phải danh từ của emerge.","example":"New details emerged after the rescue, but their emergence did not indicate a new emergency."},{"number":279,"term":"relative · relatively","sourceTerm":"relative · relatively","spoken":"relative , relatively","ipa":"relative /ˈrɛlətɪv/ · relatively /ˈrɛlətɪvli/","type":"adjective · adverb","meaning":"tương đối, được xét trong sự so sánh · khá, tương đối","definition":"Considered in comparison with something else rather than as an absolute; relatively means to a moderate degree.","note":"relatively + tính từ/trạng từ mang nghĩa khá/tương đối; relative còn là danh từ “họ hàng” trong văn cảnh khác.","example":"The first stage was relatively safe, but its safety was relative to the much harder final climb."},{"number":280,"term":"set a record # break a record # hold a record","sourceTerm":"set a record # break a record # hold a record","spoken":"set a record , break a record , hold a record","ipa":"set /sɛt/ · record /ˈrɛkɚd/ · break /breɪk/ · hold /hoʊld/","type":"word / phrase","meaning":"lập kỉ lục · phá kỉ lục · giữ kỉ lục","definition":"To achieve the best, highest, fastest, or most extreme result officially known.","note":"set a record: lập kỉ lục; break a record: phá kỉ lục đã có; hold a record: giữ kỉ lục.","example":"She set the record in 2024 and still holds it, although another climber hopes to break it."},{"number":281,"term":"better st","sourceTerm":"better (v) st","spoken":"better something","ipa":"better /ˈbɛtɚ/","type":"verb · phrase / pattern","meaning":"cải thiện, làm cho tốt hơn","definition":"To improve something or achieve a result greater than an earlier one.","note":"better có thể là động từ ngoại động từ: better a result/record/performance. Không thêm than sau tân ngữ.","example":"The athlete returned the following year and bettered her previous time by three minutes."},{"number":282,"term":"conquer","sourceTerm":"conquer (v)","spoken":"conquer","ipa":"conquer /ˈkɑːŋkɚ/","type":"verb","meaning":"chinh phục (thử thách…)","definition":"To successfully overcome a difficult challenge, fear, place, or opponent.","note":"conquer a fear/challenge/mountain; trong văn cảnh lịch sử, conquer còn là chiếm được lãnh thổ bằng vũ lực.","example":"Careful training helped the climber conquer her fear of extreme heights."},{"number":283,"term":"ease","sourceTerm":"ease (v) · (n)","spoken":"ease","ipa":"ease /iːz/","type":"verb · noun","meaning":"làm dịu, làm dễ dàng hơn · sự dễ dàng, thoải mái","definition":"To make pain, difficulty, or worry less severe; ease is the state of being comfortable or without difficulty.","note":"ease pain/pressure/tension: làm dịu; with ease: một cách dễ dàng; at ease: thoải mái.","example":"A guide eased the group's concerns by completing the first section of the route with ease."},{"number":284,"term":"geology · geologist · geological","sourceTerm":"geology · geologist · geological","spoken":"geology , geologist , geological","ipa":"geology /dʒiˈɑːlədʒi/ · geologist /dʒiˈɑːlədʒəst/ · geological /ˌdʒiəˈlɑːdʒɪkəl/","type":"noun · noun · adjective","meaning":"địa chất học · nhà địa chất học · thuộc về địa chất","definition":"Geology is the study of Earth's rocks and structure; a geologist works in this field, and geological describes it.","note":"","example":"A geologist examined the area's geological structure before the climbing route was opened."},{"number":285,"term":"descend ~ go down >< ascend ~ go up","sourceTerm":"descend ~ go down >< ascend ~ go up","spoken":"descend , go down , ascend , go up","ipa":"descend /dɪˈsɛnd/ · go /ɡoʊ/ · down /daʊn/ · ascend /əˈsɛnd/ · up /ʌp/","type":"verb · phrasal verb · verb · phrasal verb","meaning":"đi xuống, hạ xuống · đi lên, lên cao","definition":"To descend is to move downward; to ascend is to move upward.","note":"ascend/descend thường trang trọng hơn go up/go down và có thể dùng không cần tân ngữ.","example":"The team ascended the northern face and then descended by a safer route."},{"number":286,"term":"accomplish ~ achieve","sourceTerm":"accomplish (v) ~ achieve (v)","spoken":"accomplish , achieve","ipa":"accomplish /əˈkɑːmplɪʃ/ · achieve /əˈtʃiːv/","type":"verb · verb","meaning":"hoàn thành, đạt được","definition":"To successfully complete a task or reach a desired result.","note":"accomplish thường đi với task/mission/objective; achieve thường đi với goal/result/success.","example":"The group accomplished its main objective and achieved a record time."},{"number":287,"term":"feat ~ achievement","sourceTerm":"feat (n) ~ achievement (n)","spoken":"feat , achievement","ipa":"feat /fiːt/ · achievement /əˈtʃiːvmənt/","type":"noun · noun","meaning":"thành tựu nổi bật, chiến tích","definition":"An impressive action or result that requires unusual skill, strength, or effort.","note":"feat nhấn mạnh hành động nổi bật và khó thực hiện; achievement rộng hơn, chỉ thành tựu đạt được nhờ nỗ lực.","example":"Crossing the valley without mechanical support was a remarkable feat of endurance."}],"pronunciationFocus":[{"entryNumber":274,"points":[{"category":"common-error","note":"thrill bắt đầu bằng cụm /θr/, không thay /θ/ bằng /t/"},{"category":"final-sound","note":"thrill kết thúc bằng /l/; thrilled kết thúc bằng cụm /ld/"}]},{"entryNumber":277,"points":[{"category":"silent-letter","note":"Chữ s trong aisle không được phát âm"},{"category":"final-sound","note":"aisle đọc là /aɪl/ và kết thúc bằng /l/"}]},{"entryNumber":278,"points":[{"category":"word-stress","note":"emerge, emergence và emergency đều nhấn âm tiết thứ hai"},{"category":"final-sound","note":"emerge kết thúc bằng /dʒ/; emergence kết thúc bằng /ns/"}]},{"entryNumber":280,"points":[{"category":"word-stress","note":"record trong các cụm set, break hoặc hold a record là danh từ /ˈrɛkɚd/ và nhấn âm đầu"},{"category":"final-sound","note":"record kết thúc bằng /d/"}]},{"entryNumber":284,"points":[{"category":"word-stress","note":"geology và geologist nhấn âm tiết thứ hai; geological chuyển trọng âm sang âm tiết chứa /lɑːdʒ/"}]},{"entryNumber":285,"points":[{"category":"word-stress","note":"descend và ascend đều nhấn âm tiết thứ hai"},{"category":"final-sound","note":"descend và ascend đều kết thúc bằng cụm /nd/"}]},{"entryNumber":287,"points":[{"category":"common-error","note":"feat có nguyên âm dài /iː/, không đọc với /ɪ/"},{"category":"final-sound","note":"feat kết thúc bằng /t/"}]}]}};
